return { q: "Résous : " + M(poly([a, B, C]) + " = 0") + ".", spec: { kind: "set", values: [...new Set([p, q / a])] }, sol: M("\\Delta = " + (B * B - 4 * a * C)) + " ; " + M("x = \\frac{" + -B + " \\pm " + Math.round(Math.sqrt(B * B - 4 * a * C)) + "}{" + 2 * a + "}") + " : " + (p * a === q ? "discriminant nul, une seule solution : " + M("S = \\{" + p + "\\}") : M("S = \\{" + p + " ; " + frac(q, a) + "\\}")) };
