if (d === 1) return { fig: FIG.disk("r = " + r + " cm"), guide: [GS("Diamètre " + M("d = 2r") + " (en cm) ?", 2 * r, M("d = 2 \\cdot " + r + " = " + 2 * r) + " cm."), GS("Périmètre " + M("P = \\pi d") + " (au centième) ?", 2 * Math.PI * r, M("P = " + 2 * r + "\\pi \\approx " + dec((2 * Math.PI * r).toFixed(2))) + " cm.", 0.01)], q: "Calcule le périmètre d'un cercle de rayon " + M(r) + " cm (valeur exacte avec π, ou au centième).", spec: { kind: "value", value: 2 * Math.PI * r, round: 0.01, exactOk: true }, traps: [TRAP(Math.PI * r * r, "Ça, c'est l'aire " + M("\\pi r^2") + ". Le périmètre vaut " + M("2\\pi r") + "."), TRAP(Math.PI * r, "Le périmètre vaut " + M("2\\pi r") + " (ou " + M("\\pi \\cdot d") + ") : n'oublie pas le facteur 2.")], sol: M("P = 2\\pi r = " + 2 * r + "\\pi \\approx " + dec((2 * Math.PI * r).toFixed(2))) + " cm." };
if (d === 2) {
if (R.rand() < 0.5) return { fig: FIG.disk("r = " + r + " cm"), guide: [GS(M("r^2") + " = ?", r * r, M(r + "^2 = " + r * r) + "."), GS("Aire " + M("A = \\pi r^2") + " (au centième) ?", Math.PI * r * r, M("A = " + r * r + "\\pi \\approx " + dec((Math.PI * r * r).toFixed(2))) + " cm².", 0.01)], q: "Calcule l'aire d'un disque de rayon " + M(r) + " cm (valeur exacte avec π, ou au centième).", spec: { kind: "value", value: Math.PI * r * r, round: 0.01, exactOk: true }, traps: [TRAP(2 * Math.PI * r, "Ça, c'est le périmètre " + M("2\\pi r") + ". L'aire vaut " + M("\\pi r^2") + "."), TRAP(Math.PI * 4 * r * r, "Tu as mis le diamètre au carré : l'aire vaut " + M("\\pi r^2") + ", avec le rayon.")], sol: M("A = \\pi r^2 = " + r * r + "\\pi \\approx " + dec((Math.PI * r * r).toFixed(2))) + " cm²." };
const D = 2 * r; return { fig: FIG.disk("d = " + D + " cm"), guide: [GS("Rayon (la moitié du diamètre, en cm) ?", r, M("r = " + D + " : 2 = " + r) + " cm."), GS(M("r^2") + " = ?", r * r, M(r + "^2 = " + r * r) + "."), GS("Aire " + M("A = \\pi r^2") + " (au centième) ?", Math.PI * r * r, M("A = " + r * r + "\\pi \\approx " + dec((Math.PI * r * r).toFixed(2))) + " cm².", 0.01)], q: "Un disque a un diamètre de " + M(D) + " cm. Calcule son aire (valeur exacte avec π, ou au centième).", spec: { kind: "value", value: Math.PI * r * r, round: 0.01, exactOk: true }, traps: [TRAP(Math.PI * D * D, "Tu as pris le diamètre comme rayon. Le rayon est la moitié : " + M("r = " + D + " : 2 = " + r) + " cm."), TRAP(Math.PI * D, "Ça, c'est le périmètre " + M("\\pi \\cdot d") + ". L'aire vaut " + M("\\pi r^2") + ".")], sol: "Rayon " + M(r) + " cm ; " + M("A = \\pi \\cdot " + r + "^2 = " + r * r + "\\pi \\approx " + dec((Math.PI * r * r).toFixed(2))) + " cm²." };
}
const a = R.pick([30, 45, 60, 72, 90, 120, 135, 150, 240]);
