V("rotation", 1,
() => { const a = R.int(1, 5), b = a + R.int(2, 6); return QV("La petite aiguille d'une horloge passe de " + a + " h à " + b + " h. De quel angle a-t-elle tourné (en degrés) ?", (b - a) * 30, M((b - a) + " \\cdot 30° = " + (b - a) * 30 + "°") + " (30° par heure).", { guide: [GS("La petite aiguille fait le tour (360°) en 12 h : degrés par heure ?", 30, "30° par heure."), GS("De " + a + " h à " + b + " h : " + M((b - a) + " \\cdot 30°") + " = ?", (b - a) * 30, M((b - a) * 30 + "°") + ".")], traps: [TRAP((b - a) * 6, "La petite aiguille avance de 30° par heure (6° par minute, c'est la grande)."), TRAP((b - a) * 15, "360° : 12 heures = 30° par heure.")] }); },
() => { const m = R.pick([10, 15, 20, 25, 40, 45]); return QV("En " + m + " minutes, de quel angle tourne la grande aiguille d'une horloge (en degrés) ?", m * 6, "6° par minute : " + M(m + " \\cdot 6° = " + m * 6 + "°") + ".", { guide: [GS("La grande aiguille fait 360° en 60 min : degrés par minute ?", 6, "6° par minute."), GS("En " + m + " min : " + M(m + " \\cdot 6°") + " = ?", m * 6, M(m * 6 + "°") + ".")], traps: [TRAP(m * 30, "30° correspond à 5 minutes ; par minute, " + M("360° : 60 = 6°") + ".") , TRAP(m, "Par minute, la grande aiguille tourne de 6°.")] }); },
);
V("rotation", 2,
() => { const n = R.pick([5, 6, 8, 9, 10]); return QV("Une étoile régulière à " + n + " branches tourne autour de son centre. Quel est le plus petit angle de rotation (non nul) qui la superpose à elle-même (en degrés) ?", 360 / n, M("360° : " + n + " = " + 360 / n + "°") + ".", { guide: [GS("Après " + n + " petites rotations, l'étoile a fait un tour : combien de degrés ?", 360, "360°."), GS("Plus petit angle : " + M("360 : " + n) + " = ?", 360 / n, M(360 / n + "°") + ".")], traps: [TRAP(180 / n, "Un tour complet mesure 360°."), TRAP(360 / (2 * n), "Une étoile à " + n + " branches revient sur elle-même après 360° : " + n + ".")] }); },
() => { const n = R.pick([3, 4, 5, 6]), k = R.int(2, n - 1); return QV("Une éolienne a " + n + " pales régulièrement espacées. De quel angle doit-elle tourner pour que chaque pale prenne la place de celle située " + k + " crans plus loin (en degrés) ?", (360 / n) * k, "Un cran : " + 360 / n + "° ; " + M(k + " \\cdot " + 360 / n + "° = " + (360 / n) * k + "°") + ".", { guide: [GS("Un cran : " + M("360 : " + n) + " = ?", 360 / n, M(360 / n + "°") + "."), GS(k + " crans ?", (360 / n) * k, M(k + " \\cdot " + 360 / n + "° = " + (360 / n) * k + "°") + ".")], traps: [TRAP(360 / n, "Un cran vaut " + 360 / n + "° ; il en faut " + k + "."), TRAP((360 / n) * (k + 1), "Un cran vaut " + 360 / n + "° ; il en faut " + k + ".")] }); },
);


const QSet = (q, values, sol) => ({ q, spec: { kind: "set", values }, sol });
const QPair = (q, values, sol) => ({ q, spec: { kind: "pair", values }, sol });
const TRIP = [[3, 4, 5], [6, 8, 10], [5, 12, 13], [8, 15, 17], [7, 24, 25], [9, 12, 15], [20, 21, 29], [12, 16, 20], [9, 40, 41]];
V("pythrec", 1,
() => { const [a, b, c] = R.pick(TRIP); return QV("Un triangle a pour côtés " + b + " cm, " + c + " cm et " + a + " cm. Pour tester s'il est rectangle, calcule le carré de son plus long côté.", c * c, "Le plus long côté est " + c + " cm : " + M(c + "^2 = " + c * c) + " (à comparer avec " + M(a + "^2 + " + b + "^2 = " + (a * a + b * b)) + ")."); },
() => { const [a, b, c] = R.pick(TRIP); return QV("Les côtés de l'angle droit d'un triangle rectangle mesurent " + a + " cm et " + b + " cm. Que vaut le carré de l'hypoténuse (en cm²) ?", c * c, M(a + "^2 + " + b + "^2 = " + a * a + " + " + b * b + " = " + c * c) + "."); },
);
V("pythrec", 2,
() => clean(() => { const ok = R.pick(TRIP), bads = [[5, 6, 8], [7, 9, 12], [6, 7, 9], [10, 11, 15], [4, 6, 7], [8, 9, 12]].sort(() => R.rand() - 0.5).slice(0, 2), k = R.int(0, 2), L = bads.slice(); L.splice(k, 0, ok);
return QV("Un seul de ces triangles est rectangle. Donne la longueur de son hypoténuse (en cm). Côtés : " + L.map((t) => "(" + t.join(", ") + ")").join("   "), ok[2], "Seul " + M(ok[0] + "^2 + " + ok[1] + "^2 = " + ok[2] + "^2") + " est vérifié : l'hypoténuse mesure " + ok[2] + " cm."); }),
() => clean(() => { const oks = TRIP.slice().sort(() => R.rand() - 0.5).slice(0, R.int(1, 2)), bads = [[5, 6, 8], [7, 9, 12], [6, 7, 9], [10, 11, 15], [4, 6, 7], [8, 9, 12]].sort(() => R.rand() - 0.5).slice(0, 4 - oks.length), L = oks.concat(bads).sort(() => R.rand() - 0.5);
return QV("Combien de ces triangles ne sont PAS rectangles ? Côtés (en cm) : " + L.map((t) => "(" + t.join(", ") + ")").join("   "), bads.length, "Rectangles : " + oks.map((t) => "(" + t.join(", ") + ")").join(", ") + ". Les " + bads.length + " autres ne vérifient pas " + M("a^2 + b^2 = c^2") + "."); }),
);
