VA("aire1", 1, () => { const l = R.int(3, 9), L = R.int(l + 1, 15); return QV("Un rectangle a une aire de " + l * L + " m² et une largeur de " + l + " m. Quelle est sa longueur (en m) ?", L, M(l * L + " : " + l + " = " + L) + " m.", { guide: [GS("Aire = longueur · largeur. Longueur = " + M(l * L + " : " + l) + " = ?", L, M(L) + " m.")], traps: [TRAP(l * L - l, "Aire = longueur · largeur : on divise l'aire par la largeur."), TRAP(l * l * L, "Pour retrouver la longueur, on divise l'aire par la largeur.")] }); });
