VA("fracrep", 2, () => { const [a, b] = R.pick([[3, 4], [2, 3], [4, 5], [5, 6]]), [c, d] = R.pick([[5, 6], [6, 7], [7, 8], [9, 10]]); if (a / b >= c / d) return VAR.fracrep[2][0](); return QV("Quelle fraction est la plus proche de 1 : " + M("\\frac{" + a + "}{" + b + "}") + " ou " + M("\\frac{" + c + "}{" + d + "}") + " ?", c / d, "Il manque " + M("\\frac{" + (b - a) + "}{" + b + "}") + " à la première et " + M("\\frac{" + (d - c) + "}{" + d + "}") + " à la seconde, qui est plus petit : " + M("\\frac{" + c + "}{" + d + "}") + ".", { guide: [GS("Combien manque-t-il à " + M("\\frac{" + a + "}{" + b + "}") + " pour faire 1 ?", (b - a) / b, M("1 - \\frac{" + a + "}{" + b + "} = \\frac{" + (b - a) + "}{" + b + "}") + "."), GS("Et à " + M("\\frac{" + c + "}{" + d + "}") + " ?", (d - c) / d, M("\\frac{" + (d - c) + "}{" + d + "}") + ", plus petit."), GS("La plus proche de 1 ?", c / d, M("\\frac{" + c + "}{" + d + "}") + ".")], traps: [TRAP(a / b, "Il manque " + (b - a) + "/" + b + " à la première et " + (d - c) + "/" + d + " à la seconde : la plus proche de 1 est celle à qui il manque le moins.")] }); });
