VA("fracconv", 3, () => { const p = R.pick([0.5, 2.5, 7.5, 12.5]); const n = p * 2, den = 200, g = gcd(n, den); return QV("Écris " + M(dec(p) + " \\%") + " sous forme de fraction irréductible. Quel est son dénominateur ?", den / g, M(dec(p) + " \\% = \\frac{" + dec(p) + "}{100} = \\frac{" + n + "}{200} = \\frac{" + n / g + "}{" + den / g + "}") + "."); });
VA("fracper", 1, () => clean(() => { const e = R.int(1, 5), a = R.int(1, 9), b = R.int(0, 9); if (a === b) return VAR.fracper[1][0](); const k = R.pick([5, 7, 9, 11]); return QV("Le nombre " + M(e + "{,}" + a + b + a + b + a + b + "\\ldots") + " répète le groupe " + a + b + ". Quel est son " + k + "e chiffre après la virgule ?", a, "Les rangs impairs donnent " + a + ", les rangs pairs " + b + " : le " + k + "e est " + a + ".", { traps: b > 1 ? [TRAP(b, "Les rangs impairs donnent " + a + " et les rangs pairs " + b + ". Le rang " + k + " est-il pair ou impair ?")] : [], guide: [GS("Rang impair → " + a + ", rang pair → " + b + ". Le rang " + k + " est impair : chiffre ?", a, M(a) + ".")] }); }));
VA("fracper", 2, () => { const [n, d] = R.pick([[4, 9], [5, 9], [7, 9], [2, 9]]); return QV("Calcule " + M("\\frac{1}{9} + \\frac{" + (n - 1) + "}{9}") + " et écris le résultat en nombre décimal. Quel chiffre se répète ?", n, M("\\frac{" + n + "}{9} = 0{,}" + String(n).repeat(4) + "\\ldots") + ".", { guide: [GS(M("\\frac{1}{9} + \\frac{" + (n - 1) + "}{9} = \\frac{?}{9}") + " : numérateur ?", n, M("\\frac{" + n + "}{9}") + "."), GS(M("\\frac{" + n + "}{9} = 0{,}" + String(n).repeat(3) + "\\ldots") + " : chiffre répété ?", n, M(n) + ".")] }); });
VA("fracper", 3, () => { const a = R.int(1, 8), b = R.int(1, 9); if (a === b) return VAR.fracper[3][0](); return QV("Écris le nombre " + M("0{,}" + a + String(b).repeat(4) + "\\ldots") + " (seul le " + b + " se répète) sous forme de fraction.", (10 * a + b - a) / 90, M("0{,}" + a + String(b).repeat(3) + "\\ldots = \\frac{" + (10 * a + b) + " - " + a + "}{90} = " + frac(9 * a + b, 90)) + ".", { traps: [TRAP((10 * a + b) / 99, "Seul le " + b + " se répète : on calcule " + M("100x - 10x = 90x") + ", d'où un dénominateur 90."), TRAP((10 * a + b) / 90, "On soustrait la partie qui ne se répète pas : numérateur " + M((10 * a + b) + " - " + a) + ".")], guide: [GS("Soit x = " + M("0{,}" + a + b + b + "\\ldots") + ". " + M("100x - 10x") + " supprime la partie qui se répète : " + M(10 * a + b + "{,}" + b + b + "\\ldots - " + a + "{,}" + b + b + "\\ldots") + " = ?", 9 * a + b, M("90x = " + (9 * a + b)) + "."), GS("Donc x = ?", (9 * a + b) / 90, M("x = " + frac(9 * a + b, 90)) + ".")] }); });
VA("litelab", 2, () => { const a = R.int(2, 9); return QX("Un carré a pour côté " + M("x + " + a) + ". Exprime son périmètre en fonction de x (forme réduite).", "4x+" + 4 * a, M("4(x + " + a + ") = 4x + " + 4 * a)); });
VA("disque", 2, () => { const r = R.int(3, 12); return Object.assign(QE("Un disque a un périmètre de " + M(2 * r + "\\pi") + " cm. Calcule son aire (valeur exacte avec π, ou au centième).", Math.PI * r * r, "Rayon " + r + " cm ; aire " + M(r * r + "\\pi") + " cm².", 0.01, [TRAP(Math.PI * 4 * r * r, "Le rayon est " + r + " cm (le périmètre donne 2r = " + 2 * r + ")."), TRAP(2 * Math.PI * r, "C'est le périmètre ; l'aire : π · r².")]), { guide: [GS("Diamètre = périmètre : π (en cm) ?", 2 * r, M(2 * r) + " cm."), GS("Rayon ?", r, M(r) + " cm."), GS("Aire " + M("\\pi r^2") + " (au centième) ?", Math.PI * r * r, M(r * r + "\\pi \\approx " + dec(+(Math.PI * r * r).toFixed(2))) + " cm².", 0.01)] }); });
VA("disque", 3, () => { const r = R.int(3, 12), a = R.pick([30, 45, 60, 90, 120]); return QV("Un secteur circulaire de rayon " + r + " cm a une aire de " + M(frac(r * r * a, 360).replace(/^(\d+)$/, "$1") + "\\pi") + " cm². Quel est son angle (en degrés) ?", a, M("\\frac{\\alpha}{360} \\cdot " + r * r + "\\pi = " + frac(r * r * a, 360) + "\\pi") + ", donc " + M("\\alpha = " + a + "°") + ".", { guide: [GS("Aire du disque entier : " + M("\\pi \\cdot " + r + "^2") + " ; le nombre devant π ?", r * r, M(r * r + "\\pi") + " cm²."), GS("Le secteur est quelle fraction du disque ? (aire du secteur : aire du disque)", a / 360, M("\\frac{" + a + "}{360}") + "."), GS("Angle = fraction · 360 ?", a, M(a + "°") + ".")], traps: [TRAP(a * 2, "Le secteur est une fraction du disque : α/360 · π · r²."), TRAP(360 - a, "Fraction du disque = α/360 : compare l'aire du secteur à π · " + r * r + ".")] }); });
VA("grandmanq", 3, () => { let c, b; do { c = R.int(4, 9); b = R.pick([4, 6, 8, 9, 12]); } while (b === c || (c * c) / b === c || (c * c) / b === b); return QV("Un parallélogramme de base " + b + " cm a la même aire qu'un carré de " + c + " cm de côté. Quelle est sa hauteur (en cm) ?", (c * c) / b, M(c + "^2 : " + b + " = " + dec(r6((c * c) / b))) + " cm.", { guide: [GS("Aire du carré (en cm²) ?", c * c, M(c + "^2 = " + c * c) + " cm²."), GS("Parallélogramme : aire = base · hauteur. Hauteur = " + M(c * c + " : " + b) + " ?", (c * c) / b, M(c * c + " : " + b + " = " + dec(r6((c * c) / b))) + " cm.")], traps: [TRAP(r6((c * 4) / b), "L'aire du carré est " + c + "² = " + c * c + " cm², pas son périmètre."), TRAP(r6((c * c) / b / 2), "Un parallélogramme : aire = base · hauteur, sans diviser par 2.")] }); });
VA("fracops", 2, () => { const [a, b] = irr(2, 7); return QV("Calcule : " + M("-\\left(\\frac{" + a + "}{" + b + "}\\right)^2"), -(a * a) / (b * b), "Le carré d'abord, puis le signe moins : " + M("-\\frac{" + a * a + "}{" + b * b + "}") + "."); });
VA("pct", 2, () => { const x = R.pick([120, 240, 360, 480]), p = R.pick([10, 15, 20, 25]); return Object.assign(QV("Un abonnement annuel coûte " + x + " CHF. Les étudiants ont " + p + " % de réduction. Combien paie un étudiant (en CHF) ?", x * (1 - p / 100), M(x + " \\cdot " + dec(1 - p / 100) + " = " + x * (1 - p / 100)) + " CHF."), { guide: [GS("Montant de la réduction : " + M(p + "\\,\\%") + " de " + M(x) + " = ?", (x * p) / 100, M("\\frac{" + p + "}{100} \\cdot " + x + " = " + (x * p) / 100) + " CHF."), GS("Prix payé ?", x * (1 - p / 100), M(x + " - " + (x * p) / 100 + " = " + x * (1 - p / 100)) + " CHF.")], traps: [TRAP((x * p) / 100, "Ça, c'est la réduction ; il faut la retirer du prix."), TRAP(x * (1 + p / 100), "C'est une réduction : le prix baisse.")] }); });
VA("vol", 1, () => { const a = R.pick([10, 20, 25]), b = R.pick([10, 12, 15, 20]), h = R.int(1, 4) * 10; return QV("Une boîte en forme de pavé a une contenance de " + (a * b * h) / 1000 + " L. Sa base mesure " + a + " cm sur " + b + " cm. Quelle est sa hauteur (en cm) ?", h, (a * b * h) / 1000 + " L = " + mille(a * b * h) + " cm³ ; " + M(mille(a * b * h) + " : " + a * b + " = " + h) + " cm."); });
VA("vol", 3, () => { const r = R.int(2, 6), h = R.int(3, 12); return QV("Un cylindre de hauteur " + h + " cm a un volume de " + M(r * r * h + "\\pi") + " cm³. Quel est son rayon (en cm) ?", r, M("r^2 = \\frac{" + r * r * h + "}{" + h + "} = " + r * r) + ", donc " + M("r = " + r) + " cm."); });
VA("carres", 2, () => { const a = R.int(1, 9), b = R.int(2, 5); return QV("Calcule : " + M("\\sqrt{0{,}" + String(a * a).padStart(2, "0") + "} + \\sqrt[3]{" + b ** 3 + "}"), r6(a / 10 + b), M(dec(a / 10) + " + " + b + " = " + dec(r6(a / 10 + b))) + "."); });
VA("carres", 3, () => { const [c, a, b] = R.pick([[13, 5, 12], [17, 8, 15], [25, 7, 24], [10, 6, 8], [15, 9, 12]]); return QV("Calcule : " + M("\\sqrt{" + c + "^2 - " + a + "^2}"), b, M("\\sqrt{" + c * c + " - " + a * a + "} = \\sqrt{" + b * b + "} = " + b) + "."); });
VA("racenc", 2, () => { const n = R.int(5, 12), k = n * n + R.int(1, n - 1); return QV("On range " + M("\\sqrt{" + k + "}") + ", " + n + " et " + (n + 1) + " dans l'ordre croissant. Lequel est au milieu ?", Math.sqrt(k), M(n * n + " < " + k + " < " + (n + 1) ** 2) + " : " + M(n + " < \\sqrt{" + k + "} < " + (n + 1)) + "."); });
VA("monomes", 3, () => { const a = R.int(2, 5), n = R.int(2, 3); return QX("Calcule : " + M("(" + a + "x^{" + n + "})^2"), a * a + "x^" + 2 * n, M(a * a + "x^{" + 2 * n + "}") + "."); });
VA("eq1", 3, () => { const a = R.int(1, 6), b = R.int(1, 5), x = 2 * a + 3 * b; return QV("Résous : " + M("\\frac{x + " + a + "}{3} = \\frac{x - " + b + "}{2}"), x, "On multiplie par 6 : " + M("2(x + " + a + ") = 3(x - " + b + ") \\iff 2x + " + 2 * a + " = 3x - " + 3 * b + " \\iff x = " + x) + "."); });
