VA("factor", 2, () => { const a = R.int(2, 9); return QX("Factorise : " + M(a * a + " - x^2"), "(" + a + "-x)(" + a + "+x)", M("(" + a + " - x)(" + a + " + x)"), { form: "product" }); });
VA("thalesrec", 3, () => clean(() => { const a = R.int(2, 6), k = R.int(2, 3), e = R.int(2, 6), d = R.int(2, 5); return QV("D ∈ [AB] et E ∈ [AC], avec AD = " + a + ", DB = " + k * a + ", AE = " + e + " et EC = " + (k * e + d) + ". De combien faut-il raccourcir [EC] (en gardant E) pour que (DE) et (BC) deviennent parallèles ?", d, "Il faudrait " + M("\\frac{EC}{AE} = \\frac{DB}{AD} = " + k) + ", donc " + M("EC = " + k * e) + " : on raccourcit de " + d + "."); }));
