VA("denombr", 3, () => { const n = R.int(5, 12); return QV("Combien de diagonales a un polygone convexe à " + n + " côtés ?", (n * (n - 3)) / 2, "De chaque sommet partent " + (n - 3) + " diagonales ; chacune est comptée deux fois : " + M("\\frac{" + n + " \\cdot " + (n - 3) + "}{2} = " + (n * (n - 3)) / 2) + "."); });
