VA("eqspec", 1, () => { const a = R.int(2, 6), b = R.int(1, 9), c = R.int(1, 9); if (a * b === c) return VAR.eqspec[1][0](); return QSet("Résous : " + M(a + "(x + " + b + ") = " + a + "x + " + c) + ". Écris « aucune » si l'équation n'a pas de solution.", [], M(a + "x + " + a * b + " = " + a + "x + " + c) + " donne " + M(a * b + " = " + c) + " : impossible, aucune solution."); });
