VA("eq3", 1, () => { const a = R.int(2, 9); return QSet("Résous : " + M("x^3 = " + a * a + "x") + ". Sépare les solutions par « ; ».", [0, a, -a], M("x(x^2 - " + a * a + ") = 0") + " : " + M("x = 0") + ", " + M("x = " + a) + " ou " + M("x = -" + a) + "."); });
VA("eq3", 3, () => { const a = R.int(1, 5), b = R.int(2, 4); if (a === b) return VAR.eq3[3][0](); return QSet("Résous : " + M("x^3 - " + a + "x^2 - " + b * b + "x + " + a * b * b + " = 0") + " (factorise par groupement). Sépare les solutions par « ; ».", [a, b, -b], M("x^2(x - " + a + ") - " + b * b + "(x - " + a + ") = (x - " + a + ")(x^2 - " + b * b + ")") + " : " + M("x = " + a) + " ou " + M("x = \\pm " + b) + "."); });
